import React from 'react';
import { AbsoluteFill, interpolate, useCurrentFrame } from 'remotion';
import { COLORS, EASINGS } from '../../brand';
import { FONT_BODY, FONT_MONO } from '../../fonts';
import { CLAMP } from '../../lib/kit';
import { CaptionTrack, CoverImage, HookTitle, ProgressBar, SAFE, ShortBg, ToolCard, Watermark, secToFrame } from '../../lib/shorts';
import { WORDS } from './words';

// short-123: generated by the daily batch. Cover held at frame 0; closes on the cover.
export const compositionConfig = { id: 'Short123', durationInSeconds: 31.3, fps: 30, width: 1080, height: 1920 };

const T = [3.5, 9.2, 14.4, 17.0, 21.8, 25.0].map((s) => secToFrame(s));
const CTA = secToFrame(28.8);

const FadeOut: React.FC<{ at: number; children: React.ReactNode }> = ({ at, children }) => {
  const frame = useCurrentFrame();
  const op = 1 - interpolate(frame, [at - 8, at + 2], [0, 1], { ...CLAMP, easing: EASINGS.easeIn });
  return <AbsoluteFill style={{ opacity: op }}>{children}</AbsoluteFill>;
};

const Line: React.FC<{ k: string; v: string; good?: boolean; bad?: boolean }> = ({ k, v, good, bad }) => (
  <div style={{ display: 'flex', justifyContent: 'space-between', fontFamily: FONT_MONO, fontSize: 32 }}>
    <span style={{ color: COLORS.d400 }}>{k}</span>
    <span style={{ color: bad ? COLORS.danger : good ? COLORS.signalAlt : COLORS.d300, fontWeight: good || bad ? 700 : 400 }}>{v}</span>
  </div>
);
const Panel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div style={{ background: COLORS.d900, borderRadius: 12, padding: '24px 26px', display: 'flex', flexDirection: 'column', gap: 16 }}>{children}</div>
);

const Short123: React.FC = () => {
  const frame = useCurrentFrame();
  const ctaOp = interpolate(frame, [CTA, CTA + 12], [0, 1], { ...CLAMP, easing: EASINGS.easeOut });
  const lines = [{ text: 'FLASH PRICE' }, { text: 'DOUBLES JAN 1', accent: true }];
  return (
    <AbsoluteFill>
      <ShortBg />
      <FadeOut at={T[0]}>
        <CoverImage src="projects/short-123/cover.png" out={T[0] - 10} />
        <HookTitle hold onDark kicker="GEMINI PRICING" lines={lines} />
      </FadeOut>
      <FadeOut at={T[1]}>
        <ToolCard name="Gemini 3.8 Flash" tagline="Today, per 1M tokens." chip="$0.75" at={T[0] - 2}>
          <Panel>
            <Line k="input /1M" v="$0.75" />
            <Line k="output /1M" v="$3.75" />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={T[2]}>
        <ToolCard name="From January 1" tagline="Per 1M tokens." chip="$1.50" at={T[1] - 2} chipColor={COLORS.danger}>
          <Panel>
            <Line k="input /1M" v="$1.50" bad />
            <Line k="output /1M" v="$7.50" bad />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={T[3]}>
        <ToolCard name="Same model" tagline="Twice the bill." chip="2X" at={T[2] - 2} chipColor={COLORS.accent2}>
          <Panel>
            <Line k="today" v="$0.75 / $3.75" />
            <Line k="Jan 1" v="$1.50 / $7.50" bad />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={T[4]}>
        <ToolCard name="Cache doubles too" tagline="Per 1M cached tokens." chip="2X" at={T[3] - 2} chipColor={COLORS.accent2}>
          <Panel>
            <Line k="today" v="$0.075" />
            <Line k="Jan 1" v="$0.15" bad />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={T[5]}>
        <ToolCard name="Through Dec 31" tagline="Today's prices hold." chip="DEC 31" at={T[4] - 2}>
          <Panel>
            <Line k="until" v="Dec 31, 2026" good />
            <Line k="then" v="Jan 1, 2027" bad />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={CTA}>
        <ToolCard name="Budget for January" tagline="If you build on Flash." chip="2X" at={T[5] - 2} chipColor={COLORS.accent2}>
          <Panel>
            <Line k="Flash input" v="$0.75 -> $1.50" bad />
            <Line k="Flash output" v="$3.75 -> $7.50" bad />
          </Panel>
        </ToolCard>
      </FadeOut>
      <AbsoluteFill style={{ opacity: ctaOp }}>
        <CoverImage src="projects/short-123/cover.png" at={CTA} />
        <HookTitle hold onDark at={CTA} kicker="GEMINI PRICING" lines={lines} />
        <div style={{ position: 'absolute', left: SAFE.side, right: SAFE.side, top: SAFE.top + 520, textAlign: 'center', fontFamily: FONT_BODY, fontWeight: 600, fontSize: 44, color: 'rgba(255,255,255,0.82)' }}>
          Google's Flash is doubling.
        </div>
      </AbsoluteFill>
      <CaptionTrack words={WORDS} />
      <Watermark at={12} />
      <ProgressBar />
    </AbsoluteFill>
  );
};
export default Short123;
